// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// AuthTest Checks authentication and returns identity.
	// (GET /api/auth.test)
	AuthTest(ctx context.Context, request AuthTestRequestObject) (AuthTestResponseObject, error)
	// ChatDelete Deletes a message the caller authored.
	// (POST /api/chat.delete)
	ChatDelete(ctx context.Context, request ChatDeleteRequestObject) (ChatDeleteResponseObject, error)
	// ChatPostMessage Posts a message and stores it.
	// (POST /api/chat.postMessage)
	ChatPostMessage(ctx context.Context, request ChatPostMessageRequestObject) (ChatPostMessageResponseObject, error)
	// ChatUpdate Updates a message the caller authored.
	// (POST /api/chat.update)
	ChatUpdate(ctx context.Context, request ChatUpdateRequestObject) (ChatUpdateResponseObject, error)
	// ConversationsHistory Returns channel messages, newest first.
	// (GET /api/conversations.history)
	ConversationsHistory(ctx context.Context, request ConversationsHistoryRequestObject) (ConversationsHistoryResponseObject, error)
	// ConversationsInfo Gets one channel.
	// (GET /api/conversations.info)
	ConversationsInfo(ctx context.Context, request ConversationsInfoRequestObject) (ConversationsInfoResponseObject, error)
	// ConversationsList Lists channels in the workspace.
	// (GET /api/conversations.list)
	ConversationsList(ctx context.Context, request ConversationsListRequestObject) (ConversationsListResponseObject, error)
	// ConversationsMembers Lists members of a channel.
	// (GET /api/conversations.members)
	ConversationsMembers(ctx context.Context, request ConversationsMembersRequestObject) (ConversationsMembersResponseObject, error)
	// ConversationsReplies Returns a thread, parent first.
	// (GET /api/conversations.replies)
	ConversationsReplies(ctx context.Context, request ConversationsRepliesRequestObject) (ConversationsRepliesResponseObject, error)
	// UsersInfo Gets one user.
	// (GET /api/users.info)
	UsersInfo(ctx context.Context, request UsersInfoRequestObject) (UsersInfoResponseObject, error)
	// UsersList Lists users in the workspace.
	// (GET /api/users.list)
	UsersList(ctx context.Context, request UsersListRequestObject) (UsersListResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

